#!/usr/bin/env python3
"""Export/restore a verified bootstrap within one CI run, without runtime caches."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import platform
import stat
import subprocess
import sys
import tempfile

from merge_verification import invalid_constant, unique_object, validate_report

ROOT = Path(__file__).resolve().parent.parent
PAYLOAD = ("stage1.ll", "rt1.ll", "rt2.ll", "bootstrap.log", "pystachy2")
TOOLS = ("clang", "opt", "llvm-as", "llvm-link", "lli")


def digest(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def read_file(path):
    if not stat.S_ISREG(path.lstat().st_mode):
        raise ValueError(f"not a regular file: {path}")
    return path.read_bytes()


def read_json(data):
    return json.loads(data, object_pairs_hook=unique_object, parse_constant=invalid_constant)


def command(root, *args):
    return subprocess.run(args, cwd=root, check=True, capture_output=True, timeout=30).stdout


def identity(root):
    """Use working-tree bytes, not index blobs; checkout paths and runner CPUs may differ."""
    tracked = command(root, "git", "ls-files", "-z").split(b"\0")
    source_hash = hashlib.sha256()
    for name in sorted(name for name in tracked if name):
        path = root / os.fsdecode(name)
        mode = path.lstat().st_mode
        if stat.S_ISLNK(mode):
            # The test corpus deliberately includes dangling links and loops. Bind link
            # identity without following it, just as Git does.
            data, kind = os.fsencode(os.readlink(path)), b"120000"
        else:
            data = read_file(path)
            kind = b"100755" if mode & 0o111 else b"100644"
        source_hash.update(name + b"\0" + kind + b"\0" + digest(data).encode() + b"\0")
    llvm = os.environ.get("PYSTACHY_LLVM", "")
    versions = {name: command(root, str(Path(llvm) / name) if llvm else name, "--version")
                .decode().splitlines()[0] for name in TOOLS}
    release = {}
    for line in Path("/etc/os-release").read_text().splitlines():
        key, _, value = line.partition("=")
        if key in ("ID", "VERSION_ID"):
            release[key] = value.strip('"')
    if platform.system() != "Linux" or not release:
        raise ValueError("bootstrap reuse requires an identified Linux ABI")
    return {"commit": command(root, "git", "rev-parse", "HEAD").decode().strip(),
            "tracked_sources_sha256": source_hash.hexdigest(),
            "system": platform.system(), "machine": platform.machine(), "os": release,
            "libc": os.confstr("CS_GNU_LIBC_VERSION"), "tools": versions,
            "python": sys.version, "python_implementation": sys.implementation.name,
            "python_version": platform.python_version(),
            "github_run_id": os.environ.get("GITHUB_RUN_ID", "")}


def validate_producer(report, current, root):
    if not isinstance(report, dict) or report.get("group") != "bootstrap":
        raise ValueError("expected a bootstrap-only producer report")
    validate_report(report, "bootstrap", ["bootstrap"])
    if report["steps"][0].get("bootstrap_reused") is True:
        raise ValueError("producer must perform its own bootstrap")
    if report["git"]["commit"] != current["commit"]:
        raise ValueError("producer commit differs from checkout")
    toolchain = report["toolchain"]
    expected = {"python": "Python " + current["python_version"],
                "clang": current["tools"]["clang"], "llvm": current["tools"]["opt"]}
    if any(toolchain.get(key) != value for key, value in expected.items()):
        raise ValueError("producer toolchain differs from checkout")
    if report.get("platform", {}).get("machine") != current["machine"]:
        raise ValueError("producer architecture differs from checkout")
    paths = [root / name for name in ("pystachy.py", "runtime.c", "runtime.py")]
    paths += sorted((root / "src").rglob("*.py"))
    for path in paths:
        data = read_file(path)
        expected = {"lines": data.count(b"\n"), "sha256": digest(data)}
        if report["sources"].get(path.relative_to(root).as_posix()) != expected:
            raise ValueError(f"producer source differs: {path.relative_to(root)}")


def validate_payload(report, files):
    step = report["steps"][0]
    if (digest(files["stage1.ll"]) != step.get("ir_sha256") or
            files["stage1.ll"].count(b"\n") != step.get("ir_lines")):
        raise ValueError("compiler IR differs from producer evidence")
    if len(files["pystachy2"]) != step.get("native_compiler_bytes"):
        raise ValueError("compiler size differs from producer evidence")
    if (step.get("runtime_ir_identical") is not True or
            digest(files["rt1.ll"]) != step.get("runtime_ir_sha256") or
            files["rt1.ll"] != files["rt2.ll"]):
        raise ValueError("runtime IR differs from producer evidence")
    if any(not files[name] for name in PAYLOAD):
        raise ValueError("empty bootstrap payload")


def write_file(path, data, executable=False):
    # Replace instead of following an existing file's symlink; no executable appears before
    # validation completes, and a partial write can never become the restored compiler.
    with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as temp:
        temporary = Path(temp.name)
        try:
            temp.write(data)
            temp.flush()
            os.chmod(temporary, 0o755 if executable else 0o644)
            os.replace(temporary, path)
        finally:
            temporary.unlink(missing_ok=True)


def export_bundle(directory, root=ROOT):
    current = identity(root)
    report_path = root / "build/verification.json"
    report = read_json(read_file(report_path))
    validate_producer(report, current, root)
    work = root / "build/verify"
    files = {name: read_file(work / name) for name in PAYLOAD}
    # Recheck both fixed points, including the two stages not needed by consumer jobs.
    for prefix, reference in (("stage", "stage1.ll"), ("rt", "rt1.ll")):
        if any(read_file(work / f"{prefix}{index}.ll") != files[reference] for index in (2, 3)):
            raise ValueError(f"{prefix} bootstrap fixed point differs")
    step = report["steps"][0]
    step.update(runtime_ir_identical=True, runtime_ir_sha256=digest(files["rt1.ll"]))
    validate_payload(report, files)
    # The bundled report precedes bundle annotations, avoiding a circular digest. The
    # authoritative producer report gets the manifest ID after all bundle files are written.
    files["verification.json"] = canonical(report)
    manifest = {"schema": 1, "identity": current,
                "sha256": {name: digest(data) for name, data in files.items()}}
    manifest_bytes = canonical(manifest)
    bundle_id = digest(manifest_bytes)
    directory.mkdir(parents=True, exist_ok=True)
    if any(directory.iterdir()):
        raise ValueError("bundle destination must be empty")
    for name, data in files.items():
        write_file(directory / name, data)
    write_file(directory / "manifest.json", manifest_bytes)
    step.update(bootstrap_bundle_id=bundle_id, bootstrap_reused=False,
                producer_seconds=step["seconds"])
    write_file(report_path, canonical(report) + b"\n")
    return bundle_id


def load_bundle(directory, root=ROOT):
    """Validate and read payload/restore fields without changing the checkout."""
    manifest_bytes = read_file(directory / "manifest.json")
    manifest = read_json(manifest_bytes)
    if not isinstance(manifest, dict) or manifest.get("schema") != 1:
        raise ValueError("unsupported bootstrap manifest")
    current = identity(root)
    if manifest.get("identity") != current:
        raise ValueError("bootstrap checkout, toolchain, ABI or workflow run identity differs")
    expected = {*PAYLOAD, "verification.json"}
    hashes = manifest.get("sha256")
    if not isinstance(hashes, dict) or set(hashes) != expected:
        raise ValueError("unexpected bootstrap payload filenames")
    files = {name: read_file(directory / name) for name in expected}
    for name, data in files.items():
        if digest(data) != hashes[name]:
            raise ValueError(f"bootstrap payload digest differs: {name}")
    report = read_json(files["verification.json"])
    validate_producer(report, current, root)
    validate_payload(report, files)
    fields = {key: value for key, value in report["steps"][0].items()
              if key not in ("name", "result", "seconds", "log")}
    fields.update(bootstrap_bundle_id=digest(manifest_bytes), bootstrap_reused=True,
                  producer_seconds=report["steps"][0]["seconds"])
    return files, fields


def restore_bundle(directory, root=ROOT):
    files, fields = load_bundle(directory, root)
    work = root / "build/verify"
    if work.parent.is_symlink() or work.is_symlink():
        raise ValueError("bootstrap destination must not be a symlink")
    work.mkdir(parents=True, exist_ok=True)
    for name in PAYLOAD:
        write_file(work / name, files[name], executable=name == "pystachy2")
    write_file(work / "bootstrap-reuse.json", canonical(fields) + b"\n")
    return fields


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=("export", "restore"))
    parser.add_argument("directory", type=Path)
    args = parser.parse_args(argv)
    try:
        result = (export_bundle if args.action == "export" else restore_bundle)(args.directory)
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        print(f"bootstrap bundle: {exc}", file=sys.stderr)
        return 1
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Fail closed when assembling the parallel CI jobs' verification reports."""
import argparse
from collections import Counter
import copy
from datetime import datetime, timezone
import importlib.util
import json
import math
import os
from pathlib import Path
import re
import subprocess
import sys

import annotation_widening
import check_example_cli
import dynany_optin
import python_int_gate

ROOT = Path(__file__).resolve().parent.parent
SUITE_STEPS = {"tests-cpython", "tests-native-0", "tests-native-1", "tests-native-2",
               "tests-opt-off-0", "tests-opt-off-1", "tests-opt-off-2", "runtime-cache", "python-free-0",
               "python-free-1", "python-free-2", "python-free-3", "ubsan-0", "ubsan-1", "ubsan-2", "ubsan-3", "ubsan-4", "gc-jit-0", "gc-jit-1", "gc-aot-0", "gc-aot-1",
               "gc-aot-2"}
# Steps that run one of the disjoint shards of the corpus (tests/verify.sh shard_cases), and how many
# shards their suite has: the name ends in the shard index.
SHARDED_STEPS = {f"{suite}-{index}": count for suite, count in
                 (("tests-native", 3), ("tests-opt-off", 3), ("python-free", 4),
                  ("ubsan", 5), ("gc-ir", 2), ("gc-jit", 2), ("gc-aot", 3))
                 for index in range(count)}
# The PR profile keeps full native coverage in two JIT workers and four AOT workers. Each alternate configuration runs
# the common deterministic sample in one worker; these are not partial shards of the full gate.
PR_NATIVE_SHARDS = {"jit": 2, "aot": 4}
PR_NATIVE_STEPS = {f"tests-native-{mode}-{index}": mode for mode, count in PR_NATIVE_SHARDS.items()
                   for index in range(count)}
SUITE_STEPS.update(PR_NATIVE_STEPS)
PR_SHARDED_STEPS = {**{name: PR_NATIVE_SHARDS[mode] for name, mode in PR_NATIVE_STEPS.items()}, "tests-opt-off-0": 1,
                    "python-free-0": 1, "ubsan-0": 1, "gc-jit-0": 1, "gc-aot-0": 1}
# The GC suites run their shards (halves in JIT, thirds in AOT) with program stress alone, compiled by
# stage 2 unstressed, after the gc-ir halves have shown the stage-2 compiler collecting every
# GC_COMPILER_INTERVAL allocations to compile every case to the same IR, messages and status. Each
# runs a sample of its shard end to end with the compiler stressed too, first: the cases at positions
# GC_SAMPLE_OFFSETS[mode] modulo GC_SAMPLE_EVERY of the shard as shard_cases lists it (tests/verify.sh)
GC_STEPS = {"gc-jit-0", "gc-jit-1", "gc-aot-0", "gc-aot-1", "gc-aot-2"}
GC_IR_STEPS = ("gc-ir-0", "gc-ir-1")
GC_COMPILER_INTERVAL = 1000
GC_SAMPLE_EVERY = 16
GC_SAMPLE_OFFSETS = {"jit": 4, "aot": 12}
# The halves of tools/scaling.py's check (tests/verify.sh's SCALING_0 and the shapes it leaves)
SCALING_STEPS = ("scaling-0", "scaling-1")
# The opt-in sweeps' shards (tests/verify.sh's dynany-optin-I and python-int-optin-I groups)
DYNANY_SHARDS = 3
PYTHON_INT_SHARDS = 3
# tests-cpython runs one case in HOSTED_SAMPLE_OF end to end (tests/verify.sh's sample_cases: those at
# positions 0 modulo HOSTED_SAMPLE_OF of the corpus in C order); it compares every case's IR, messages
# and exit status with stage 2's
HOSTED_SAMPLE_OF = 64
# The kinds of program whose run takes the CPython-hosted driver past the IR along a path of its own
# (tests/verify.sh's hosted_strata, which names the same kinds and tests them alike), of which
# tests-cpython also runs one each end to end: a test of a program's path in the checkout
HOSTED_STRATA = {
    "sigint": lambda path: b"kill -INT" in path.read_bytes(),   # (it sends itself SIGINT)
    "full": lambda path: path.with_suffix(".full").is_file(),   # (stdout /dev/full)
    "in": lambda path: path.with_suffix(".in").is_file(),       # (stdin)
    "path": lambda path: path.with_suffix(".path").is_file(),   # (PYSTACHY_PATH)
    "ffi": lambda path: re.search(rb"(?m)^(import|from) ffi( |$)", path.read_bytes()) is not None,
}


def hosted_stratum(kind, case, root=ROOT):
    """Is CASE a program of the corpus, in ROOT, of the hosted driver's path KIND (HOSTED_STRATA)?"""
    if not isinstance(case, str) or not re.fullmatch(r"tests/programs/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+\.py", case):
        return False
    path = root / case
    return path.is_file() and path.with_suffix(".out").is_file() and HOSTED_STRATA[kind](path)


def hosted_sample(strata, root=ROOT):
    """tests-cpython's end-to-end sample in ROOT (tests/verify.sh): the cases at positions 0 modulo
    HOSTED_SAMPLE_OF of tests/corpus.sh's corpus, listed in C order as verify.sh lists it, and the
    programs STRATA names, once each, in the corpus's order."""
    cases = subprocess.run(["sh", "-c", ". tests/corpus.sh; LC_ALL=C; export LC_ALL; corpus"], cwd=root,
                           env={**os.environ, "LC_ALL": "C"}, check=True, capture_output=True, text=True,
                           timeout=60).stdout.splitlines()
    if not cases:
        raise ValueError(f"{root}: no case in the corpus")
    wanted = set(cases[::HOSTED_SAMPLE_OF]) | set(strata.values())
    return [case for case in cases if case in wanted]


def parse_groups(text):
    """Read the harness's public contract, checking that no check is omitted or repeated."""
    groups = {}
    for line in text.splitlines():
        words = line.split()
        if not words:
            continue
        name, *steps = words
        if name in groups:
            raise ValueError(f"duplicate group in --list: {name}")
        if not steps or steps[0] != "bootstrap" or len(set(steps)) != len(steps):
            raise ValueError(f"invalid step list for {name}: bootstrap must come first, once")
        groups[name] = steps
    if not groups or next(iter(groups)) != "all" or len(groups) < 2:
        raise ValueError("--list must begin with all, followed by the CI groups")
    if "bootstrap" in groups and groups["bootstrap"] != ["bootstrap"]:
        raise ValueError("the bootstrap producer must run only bootstrap")
    covered = Counter(step for name, steps in groups.items() if name != "all"
                      for step in steps if step != "bootstrap")
    if covered != Counter(groups["all"][1:]):
        raise ValueError("CI groups must cover every all step exactly once, except bootstrap")
    return groups


def scaling_shapes():
    """The shapes of tools/scaling.py, which scaling-0 and scaling-1 share out."""
    spec = importlib.util.spec_from_file_location("scaling", ROOT / "tools/scaling.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return list(module.SHAPES)


def load_groups(profile="full"):
    if profile not in ("full", "pr"):
        raise ValueError(f"unknown verification profile: {profile}")
    result = subprocess.run([str(ROOT / "tests/verify.sh"), "--list"], cwd=ROOT,
                            env={**os.environ, "VERIFY_PROFILE": profile},
                            check=True, capture_output=True, text=True, timeout=10)
    return parse_groups(result.stdout)


def pr_selection():
    """Recompute the PR selection from trusted checkout inputs, never from an artifact's list."""
    import ci_sample
    base = os.environ.get("CI_BASE_SHA") or None
    return ci_sample.manifest(root=ROOT, base=base)


def case_checks(cases, modes):
    """Count tests/run.sh's exact checks, as tests/verify.sh's checks does."""
    import ci_sample
    return ci_sample.expected_checks(cases, modes, root=ROOT)


def validate_pr_case_step(step, selection, label):
    """Bind the PR step's exact cases and counts to the independent full shard or sparse sample."""
    name = step["name"]
    if name.startswith("tests-native-"):
        index = int(name.rsplit("-", 1)[1])
        count = PR_NATIVE_SHARDS[PR_NATIVE_STEPS[name]]
        selected = subprocess.run(["sh", "-c", f". tests/corpus.sh; corpus_shard {index} {count}"], cwd=ROOT,
                                  env={**os.environ, "LC_ALL": "C"}, check=True, capture_output=True,
                                  text=True, timeout=60).stdout.splitlines()
    else:
        selected = selection["cases"]
    if not selected or step.get("selected_cases") != selected:
        raise ValueError(f"{label}: selected cases differ from the checkout's {name} selection")
    if name in GC_STEPS:
        mode = "jit" if name.startswith("gc-jit") else "aot"
        offset = GC_SAMPLE_OFFSETS[mode]
        sample = selected[offset::GC_SAMPLE_EVERY]
        rest = [case for position, case in enumerate(selected) if position % GC_SAMPLE_EVERY != offset]
        if (step["shard_cases"] != len(selected) or step["expected"] != case_checks(rest, [mode]) or
                step["stressed_sample"]["expected"] != case_checks(sample, [mode])):
            raise ValueError(f"{label}: sparse GC case/check coverage differs from its selection")
        return
    if name.startswith("ubsan-"):
        expected = 2 * case_checks(selected, ["jit"])
        if (step.get("ir_identical") is not True or step.get("modes") != ["aot", "jit"] or
                step.get("cflags") != "-fsanitize=undefined -fno-sanitize-recover=all --rtlib=compiler-rt" or
                not isinstance(step.get("jit_preload"), str) or not step["jit_preload"]):
            raise ValueError(f"{label}: missing instrumented UBSan JIT/AOT and compiler identity evidence")
    elif name in PR_NATIVE_STEPS:
        mode = PR_NATIVE_STEPS[name]
        expected = case_checks(selected, [mode])
        if step.get("compiler") != "stage2" or step.get("modes") != [mode]:
            raise ValueError(f"{label}: expected the stage-2 compiler in {mode} only")
    else:
        expected = case_checks(selected, ["jit", "aot"])
        if name.startswith("python-free-"):
            if (step.get("python_on_path") is not False or step.get("ir_identical") is not True or
                    not isinstance(step.get("path_tools"), list) or not step["path_tools"] or
                    any(str(tool).startswith("python") for tool in step["path_tools"])):
                raise ValueError(f"{label}: missing Python-free rebuild and PATH isolation evidence")
        elif step.get("compiler") != "stage2" or step.get("modes") != ["jit", "aot"]:
            raise ValueError(f"{label}: expected the stage-2 compiler in JIT and AOT")
        if name.startswith("tests-opt-off-") and step.get("PYSTACHY_OPT") != ["-all"]:
            raise ValueError(f"{label}: all optimization passes must be disabled")
    if step["expected"] != expected:
        raise ValueError(f"{label}: check count differs from its exact selected cases")


def validate_pr_native_coverage(reports):
    """Require every case in each execution mode exactly once, including opt-in baselines.

    Both mode groups keep the full corpus: rejection and parser checks repeat, while every
    accepted program runs exactly once in JIT and once in AOT. Counts alone cannot prove this.
    """
    import ci_sample
    cases = ci_sample.corpus(ROOT)
    steps = [step for report in reports.values() for step in report["steps"]
             if step["name"].startswith("tests-native")]
    if Counter(step["name"] for step in steps) != Counter(PR_NATIVE_STEPS.keys()):
        raise ValueError("PR native coverage requires two complete JIT halves and four AOT quarters")
    pairs = []
    for step in steps:
        mode = PR_NATIVE_STEPS[step["name"]]
        if (step.get("compiler") != "stage2" or step.get("modes") != [mode] or
                step.get("passed") != step["expected"] or step.get("failed") != 0):
            raise ValueError("PR native coverage requires successful stage-2 checks in the declared mode")
        pairs.extend((case, mode) for case in step["selected_cases"])
    expected = {(case, mode) for case in cases for mode in ("jit", "aot")}
    if len(pairs) != len(expected) or set(pairs) != expected:
        raise ValueError("PR native shards must cover every corpus case and mode exactly once")
    for mode in ("jit", "aot"):
        if sum(step["expected"] for step in steps if step["modes"] == [mode]) != case_checks(cases, [mode]):
            raise ValueError(f"PR native {mode} shards must cover all execution, rejection and parser checks")


def unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def invalid_constant(value):
    raise ValueError(f"invalid JSON number: {value}")


def number(value, label):
    if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
        raise ValueError(f"{label}: expected a finite, nonnegative duration")
    return value


def integer(value, label, minimum=0):
    if type(value) is not int or value < minimum:
        raise ValueError(f"{label}: expected an integer >= {minimum}")
    return value


def benchmark_programs():
    """The top-level bench/*.py inputs of verify.sh, independently of an artifact's counts."""
    return sorted(path.stem for path in (ROOT / "bench").glob("*.py")
                  if path.is_file() and not path.name.startswith("."))


def validate_benchmarks(step, label):
    programs = benchmark_programs()
    if not programs:
        raise ValueError(f"{label}: no benchmark programs in the checkout")
    for field in ("programs", "identical"):
        if integer(step.get(field), f"{label}.{field}", 1) != len(programs):
            raise ValueError(f"{label}: {field} must count every bench/*.py program")
    rows = step.get("timings")
    if not isinstance(rows, list) or any(not isinstance(row, dict) for row in rows):
        raise ValueError(f"{label}: missing benchmark timing rows")
    names = [row.get("name") for row in rows]
    if any(not isinstance(name, str) for name in names) or sorted(names) != programs:
        raise ValueError(f"{label}: timing rows must name every bench/*.py program exactly once")
    for row in rows:
        case = f"{label}.{row['name']}"
        if row.get("identical") is not True:
            raise ValueError(f"{case}: missing CPython/JIT/AOT output parity")
        for field in ("cpython_seconds", "jit_seconds", "aot_build_seconds", "aot_seconds"):
            if number(row.get(field), f"{case}.{field}") == 0:
                raise ValueError(f"{case}.{field}: expected a positive duration")


def validate_report(report, group, expected, profile="full", selection=None):
    if not isinstance(report, dict) or report.get("project") != "Pystachy":
        raise ValueError(f"{group}: not a Pystachy verification report")
    if profile not in ("full", "pr") or report.get("profile", "full") != profile:
        raise ValueError(f"{group}: verification profile differs from required {profile}")
    if profile == "pr":
        selection = pr_selection() if selection is None else selection
        if report.get("selection") != selection:
            raise ValueError(f"{group}: PR selection identity differs from this checkout and base")
    sharded_steps = PR_SHARDED_STEPS if profile == "pr" else SHARDED_STEPS
    optin_cases = ([case for case in selection["cases"] if case.startswith("tests/programs/")]
                   if profile == "pr" else None)
    if report.get("result") != "pass":
        raise ValueError(f"{group}: verification did not pass")
    summary, steps = report.get("summary"), report.get("steps")
    if not isinstance(summary, dict) or not isinstance(steps, list):
        raise ValueError(f"{group}: missing summary or steps")
    names = [step.get("name") if isinstance(step, dict) else None for step in steps]
    if names != expected:
        raise ValueError(f"{group}: step names/order differ: expected {expected}, got {names}")
    for key, value in (("steps", len(expected)), ("passed", len(expected)), ("failed", 0)):
        if integer(summary.get(key), f"{group}.summary.{key}") != value:
            raise ValueError(f"{group}: summary {key} must be {value}")
    number(summary.get("seconds"), f"{group}.summary.seconds")
    for step in steps:
        label = f"{group}.{step['name']}"
        if step.get("result") != "pass":
            raise ValueError(f"{label}: step did not pass")
        number(step.get("seconds"), f"{label}.seconds")
        if "failed" in step and integer(step["failed"], f"{label}.failed") != 0:
